<?php date_default_timezone_set('Asia/Kolkata');$date=date('d F Y');$time=date('h:i:s A');$day=date('l');?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Date, Time & Day</title><link rel="stylesheet" href="../assets/css/program.css"><meta http-equiv="refresh" content="1"></head><body><header class="nav"><a class="brand" href="../"><b>P</b> PHP LAB</a><a class="back" href="../">← Back to programs</a></header><main class="wrap"><div class="eyebrow">PROGRAM B · PHP DATE FUNCTIONS</div><h1 class="title">Time, right now.</h1><p class="subtitle">The current date, time and day generated using PHP.</p><section class="panel"><div class="symbol">◷</div><div class="eyebrow">CURRENT LOCAL TIME · INDIA</div><div class="stat" style="display:block;font-size:34px"><?= $time ?></div><div class="field"><label>Current date</label><div class="secondary" style="display:block"><?= $date ?></div></div><div class="field"><label>Day of the week</label><div class="secondary" style="display:block"><?= $day ?></div></div><p class="muted">Timezone: Asia/Kolkata .</p></section></main><footer class="footer">PHP LAB STUDIO · PROGRAM B</footer></body></html>